import os
import sys
import time
import json
import threading
import winreg
import base64
import io
import pygetwindow as gw
from pypresence import Presence
import win32api
import pystray
from PIL import Image

CLIENT_ID = "1456023375561490474"
APP_NAME = "FLStudioDiscordRPC"
SETTINGS_FILE = "fl_rpc_settings.json"
REG_PATH = r"Software\Microsoft\Windows\CurrentVersion\Run"

ICON_BASE64 = (
    ""
)

DEFAULT_SETTINGS = {
    "hide_project_name": False,
    "run_at_startup": False
}

settings_lock = threading.Lock()
rpc_lock = threading.Lock()

settings = {}
rpc = None
start_time = int(time.time())
stop_event = threading.Event()
force_rpc_refresh = threading.Event()

def load_settings():
    if os.path.exists(SETTINGS_FILE):
        with open(SETTINGS_FILE, "r") as f:
            data = json.load(f)
            for k, v in DEFAULT_SETTINGS.items():
                data.setdefault(k, v)
            return data
    return DEFAULT_SETTINGS.copy()

def save_settings():
    with open(SETTINGS_FILE, "w") as f:
        json.dump(settings, f, indent=2)

def enable_startup():
    exe = sys.executable
    script = os.path.abspath(__file__)
    cmd = f'"{exe}" "{script}"'
    with winreg.OpenKey(winreg.HKEY_CURRENT_USER, REG_PATH, 0, winreg.KEY_SET_VALUE) as k:
        winreg.SetValueEx(k, APP_NAME, 0, winreg.REG_SZ, cmd)

def disable_startup():
    with winreg.OpenKey(winreg.HKEY_CURRENT_USER, REG_PATH, 0, winreg.KEY_SET_VALUE) as k:
        try:
            winreg.DeleteValue(k, APP_NAME)
        except FileNotFoundError:
            pass

def is_in_startup():
    try:
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, REG_PATH, 0, winreg.KEY_READ) as k:
            winreg.QueryValueEx(k, APP_NAME)
            return True
    except Exception:
        return False

def get_idle_time():
    return (win32api.GetTickCount() - win32api.GetLastInputInfo()) / 1000

def get_fl_project():
    for w in gw.getWindowsWithTitle("FL Studio"):
        if " - FL Studio" in w.title:
            return w.title.split(" - FL Studio")[0]
        if w.title.startswith("FL Studio"):
            return "Empty Project"
    return None

def send_rpc(state, details):
    with rpc_lock:
        if rpc:
            rpc.update(
                state=state,
                details=details,
                large_image="fl_logo",
                large_text="FL Studio",
                start=start_time
            )

def rpc_loop():
    global rpc
    try:
        client = Presence(CLIENT_ID)
        client.connect()
        with rpc_lock:
            rpc = client
    except Exception:
        return

    last_state = None
    last_details = None

    while not stop_event.is_set():
        project = get_fl_project()

        if not project:
            with rpc_lock:
                try:
                    rpc.clear()
                except Exception:
                    pass
            last_state = None
            last_details = None
            time.sleep(5)
            continue

        idle = get_idle_time() > 10
        details = "Idle" if idle else "Composing Music"

        with settings_lock:
            hide = settings["hide_project_name"]

        state = "Working in FL Studio" if hide else f"Project: {project}"

        if force_rpc_refresh.is_set() or state != last_state or details != last_details:
            send_rpc(state, details)
            last_state = state
            last_details = details
            force_rpc_refresh.clear()

        for _ in range(15):
            if stop_event.is_set():
                break
            time.sleep(1)

    with rpc_lock:
        try:
            rpc.clear()
            rpc.close()
        except Exception:
            pass
        rpc = None

def toggle_hide_project(icon, item):
    with settings_lock:
        settings["hide_project_name"] = not settings["hide_project_name"]
        save_settings()
    force_rpc_refresh.set()
    icon.menu = build_menu()

def toggle_startup(icon, item):
    with settings_lock:
        settings["run_at_startup"] = not settings["run_at_startup"]
        save_settings()

    if settings["run_at_startup"]:
        enable_startup()
    else:
        disable_startup()

    force_rpc_refresh.set()
    icon.menu = build_menu()

def quit_app(icon, item):
    stop_event.set()
    icon.stop()

def build_menu():
    return pystray.Menu(
        pystray.MenuItem(
            f"Hide project name [{'ON' if settings['hide_project_name'] else 'OFF'}]",
            toggle_hide_project
        ),
        pystray.MenuItem(
            f"Run on startup [{'ON' if settings['run_at_startup'] else 'OFF'}]",
            toggle_startup
        ),
        pystray.MenuItem("Quit", quit_app)
    )

def tray_loop():
    image_bytes = base64.b64decode(ICON_BASE64)
    image = Image.open(io.BytesIO(image_bytes))
    icon = pystray.Icon(APP_NAME, image, "Fruity RPC", build_menu())
    icon.run()

def main():
    global settings
    settings = load_settings()

    if settings["run_at_startup"] and not is_in_startup():
        enable_startup()
    if not settings["run_at_startup"] and is_in_startup():
        disable_startup()

    threading.Thread(target=rpc_loop, daemon=True).start()
    tray_loop()

if __name__ == "__main__":
    main()
